 aa=res.target_disassembly[a0:a1];bb=res.candidate_disassembly[b0:b1];pairs=list(zip(aa,bb));offsets=frozenset((a.offset,b.offset) for a,b in pairs);rows=[];refs=[]
 for k,(a,b) in enumerate(pairs):
  assert a.size==b.size,(a0+k,b0+k,a,b)
  if a.masked_references or b.masked_references:
   assert tuple((r.operand_index,r.kind) for r in a.masked_references)==tuple((r.operand_index,r.kind) for r in b.masked_references)
   state=m._reference_status(a.masked_references,b.masked_references,aligned_instruction_offsets=offsets,strict=True);assert state=='ok'
   entry=m.MaskedOperandAuditEntry(a0+k,b0+k,a.offset,b.offset,a.address,b.address,a.text,a.masked_references,b.masked_references,state);refs.extend(m._masked_audit_cache_payload(m.MaskedOperandAudit((entry,))))
  left=bytearray(native[a.offset:a.offset+a.size]);right=bytearray(obj.data[b.offset:b.offset+b.size]);ta=next(md.disasm(bytes(left),a.offset));cb=next(md.disasm(bytes(right),b.offset));masked=[]
  for ref in b.masked_references:
   if ref.source!='reloc':continue
   field='imm' if ref.kind=='imm' else 'disp';offset=getattr(cb,field+'_offset');size=getattr(cb,field+'_size');assert offset==getattr(ta,field+'_offset') and size==getattr(ta,field+'_size');masked.append([offset,size]);left[offset:offset+size]=right[offset:offset+size]=bytes(size)
  local_a=m._local_branch_offsets(a);local_b=m._local_branch_offsets(b)
  assert len(local_a)==len(local_b)
  for dest_a,dest_b in zip(local_a,local_b):
   if (dest_a,dest_b) not in offsets:
    assert destination_context is not None and (dest_a,dest_b) in destination_context,(a0+k,b0+k,dest_a,dest_b)
  if local_b and b.offset+cb.imm_offset in obj.relocation_offsets:
   assert len(local_b)==1;size=cb.imm_size;right[cb.imm_offset:cb.imm_offset+size]=((local_b[0]-b.offset-b.size)%(1<<(8*size))).to_bytes(size,'little')
  rows.append({'region_index':k,'target_index':a0+k,'candidate_index':b0+k,'target_offset':a.offset,'candidate_offset':b.offset,'target':a.text,'candidate':b.text,'native_raw':native[a.offset:a.offset+a.size].hex(),'candidate_raw':obj.data[b.offset:b.offset+b.size].hex(),'audited_native':left.hex(),'audited_candidate':right.hex(),'masked_external_fields':masked,'local_branch_target_pairs':list(zip(local_a,local_b))})
